(function(){'use strict';const $=id=>document.getElementById(id);let me=null,revision=0,busy=false,cloudLoaded=false;const STORAGE='pocket-critters-v2-battle';
const wrap=document.createElement('div');wrap.id='accountLayer';wrap.hidden=true;wrap.innerHTML=`<section class="panel account-panel"><button id="accountClose" class="account-close" aria-label="닫기">×</button><small>YOUR CREW. EVERYWHERE.</small><h2 id="accountTitle">우리 팀의 시작.</h2><p id="accountIntro">계정을 만들고 다른 기기에서도 전투를 이어가세요.</p><div id="authForms"><div class="segmented"><button id="loginTab" class="selected">로그인</button><button id="signupTab">회원가입</button></div><form id="accountForm"><label id="nicknameRow" hidden>닉네임<input id="accountNickname" name="nickname" autocomplete="nickname" minlength="2" maxlength="16" placeholder="2~16자"></label><label>이메일<input id="accountEmail" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></label><label>비밀번호<input id="accountPassword" name="password" type="password" autocomplete="current-password" required minlength="10" maxlength="128" placeholder="10자 이상"></label><p id="signupNote" hidden>무료 회원 서버를 사용합니다. 가입 확인 메일이 도착하면 링크를 눌러 주세요.</p><button class="primary" id="authSubmit" type="submit">로그인 →</button></form></div><div id="signedIn" hidden><div class="profile-badge">⚑ <b id="profileNick"></b></div><p id="profileEmail"></p><div class="cloud-actions"><button id="cloudPull">클라우드 전투 불러오기 ↓</button><button id="cloudPush">현재 전투 클라우드 저장 ↑</button></div><p class="cloud-warning">다른 기기에서 이어할 때는 먼저 불러오세요. 자동 저장은 기기 내부에 이루어지고, 클라우드 저장은 위 버튼으로 실행합니다.</p><button id="accountLogout">로그아웃</button><details><summary>계정 삭제</summary><p>이 계정과 클라우드 전투를 영구 삭제합니다. 기기 내부 전투는 유지됩니다.</p><input id="deletePassword" type="password" autocomplete="current-password" placeholder="비밀번호 재입력"><button id="accountDelete">계정 영구 삭제</button></details></div><p id="accountMessage" role="status" aria-live="polite"></p><small id="accountServerNote">서버에 연결된 설치형 게임에서 사용할 수 있습니다.</small></section>`;document.body.append(wrap);
let signup=false;function mode(v){signup=v;$('nicknameRow').hidden=!v;$('signupNote').hidden=!v;$('accountNickname').required=v;$('authSubmit').textContent=v?'회원가입하고 시작 →':'로그인 →';$('accountPassword').autocomplete=v?'new-password':'current-password';$('signupTab').classList.toggle('selected',v);$('loginTab').classList.toggle('selected',!v);message('')}
function message(text,error=false){$('accountMessage').textContent=text;$('accountMessage').style.color=error?'#ffbca5':'#b9e7c9'}
let cloudPromise=null;async function api(route,method='GET',body){if(location.protocol==='file:')throw Error('회원가입은 배포된 게임 주소에서 사용할 수 있습니다.');cloudPromise??=CritterCloud.Cloud.connect().catch(e=>{cloudPromise=null;throw e});const cloud=await cloudPromise;if(route==='/me')return {user:cloud.profile(await cloud.me())};if(route==='/auth/register')return cloud.signup(body);if(route==='/auth/login')return cloud.login(body);if(route==='/auth/logout'){await cloud.logout();return {ok:true}}if(route==='/save'&&method==='GET')return cloud.pull();if(route==='/save'&&method==='PUT')return cloud.push(body.revision,body.save);if(route==='/account'){await cloud.remove(body.password);return {ok:true}}throw Error('지원하지 않는 요청입니다.');}
function profile(){let logged=!!me;$('authForms').hidden=logged;$('signedIn').hidden=!logged;$('accountTitle').textContent=logged?'반가워요, 탐험가.':'우리 팀의 시작.';$('accountIntro').textContent=logged?'나의 크루와 전투를 관리하세요.':'계정을 만들고 다른 기기에서도 전투를 이어가세요.';if(me){$('profileNick').textContent=me.nickname;$('profileEmail').textContent=me.email}$('accountOpen').textContent=me?me.nickname+' ⚑':'로그인 / 가입';$('accountServerNote').textContent=me?'계정 연결됨 · 현재 버전 '+(window.PC_RELEASE?.version||'0.3.0'):'서버에 연결된 설치형 게임에서 사용할 수 있습니다.';}
async function action(fn){if(busy)return;busy=true;$('authSubmit').disabled=true;try{await fn()}catch(e){message(e.message,true)}finally{busy=false;$('authSubmit').disabled=false}}
function open(){window.dispatchEvent(new CustomEvent('pc:external-pause'));wrap.hidden=false;profile();if(location.protocol==='file:')message('오프라인 체험 모드입니다. 실제 회원가입은 계정 서버 배포 후 사용할 수 있습니다.',true)}
const button=document.createElement('button');button.id='accountOpen';button.textContent='로그인 / 가입';document.querySelector('.top-actions').prepend(button);button.onclick=open;const pauseAccount=document.createElement('button');pauseAccount.textContent='계정 / 클라우드 전투';pauseAccount.onclick=open;document.getElementById('pauseMenu').append(pauseAccount);$('accountClose').onclick=()=>{wrap.hidden=true;$('accountPassword').value='';$('deletePassword').value=''};$('loginTab').onclick=()=>mode(false);$('signupTab').onclick=()=>mode(true);
$('accountForm').onsubmit=e=>{e.preventDefault();action(async()=>{let b=await api(signup?'/auth/register':'/auth/login','POST',{email:$('accountEmail').value,password:$('accountPassword').value,nickname:$('accountNickname').value});me=b.user;revision=0;cloudLoaded=false;$('accountPassword').value='';profile();message(b.confirmationRequired?'가입 확인 메일을 확인한 후 로그인해 주세요.':signup?'계정이 생성되었습니다.':'로그인했습니다. 먼저 클라우드 전투를 확인해 주세요.');})};
$('cloudPull').onclick=()=>action(async()=>{let data=await api('/save');revision=data.revision;cloudLoaded=true;if(!data.save){message('아직 클라우드 전투가 없습니다. 이 기기의 전투를 저장할 수 있어요.');return}if(!confirm('이 기기에 저장된 전투를 클라우드 전투로 교체할까요?'))return;localStorage.setItem(STORAGE,JSON.stringify(data.save));window.dispatchEvent(new CustomEvent('pc:cloud-loaded'));message('전투를 불러왔습니다. 메인 화면의 이어하기를 선택하세요.')});
$('cloudPush').onclick=()=>action(async()=>{if(!cloudLoaded){let b=await api('/save');revision=b.revision;cloudLoaded=true;if(b.save){message('기존 클라우드 전투가 있습니다. 먼저 불러오세요. 저장하려면 다시 눌러 덮어쓰기를 확인하세요.',true);return}}let raw=localStorage.getItem(STORAGE);if(!raw)throw Error('먼저 전투를 시작해 저장 상태를 만들어 주세요.');if(revision>0&&!confirm('기존 클라우드 전투를 현재 기기의 전투로 덮어쓸까요?'))return;let b=await api('/save','PUT',{revision,save:JSON.parse(raw)});revision=b.revision;message('클라우드에 저장했습니다. 저장 버전 '+revision)});
$('accountLogout').onclick=()=>action(async()=>{await api('/auth/logout','POST',{});me=null;revision=0;cloudLoaded=false;profile();message('로그아웃했습니다.')});$('accountDelete').onclick=()=>action(async()=>{if(!confirm('계정과 클라우드 전투를 영구 삭제할까요? 복구할 수 없습니다.'))return;await api('/account','DELETE',{password:$('deletePassword').value});me=null;revision=0;cloudLoaded=false;$('deletePassword').value='';profile();message('계정과 클라우드 데이터가 삭제되었습니다.')});
if(location.protocol!=='file:')api('/me').then(b=>{me=b.user;profile()}).catch(()=>{$('accountOpen').textContent='게스트 / 계정'});else profile();
})();

